    before: ["echo pre"]
    after: ["echo post"]
settings:
  logging: true
  parallel: true
  max_parallel: 8
"#,
        )
        .unwrap();

        let yaml = serde_yaml::to_string(&config).unwrap();

        assert!(
            yaml.contains("required"),
            "non-default required should be present"
