    #[test]
    fn parses_all_check() {
        let yaml = r#"
steps:
  deps:
    command: "yarn install"
    completed_check:
      type: all
      checks:
        - type: file_exists
          path: "node_modules"
        - type: command_succeeds
          command: "yarn check"
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
